#!/bin/sh
set -eu

APP_DIR=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
cd "$APP_DIR"

case "${AUTO_MIGRATE:-1}" in
    1) php "$APP_DIR/php/migrate.php" ;;
    0) printf '%s\n' 'Migraciones automáticas desactivadas (AUTO_MIGRATE=0).' ;;
    *) printf '%s\n' 'AUTO_MIGRATE debe ser 1 o 0.' >&2; exit 1 ;;
esac

# Retain the PHP/Nginx startup generated by Nixpacks 1.41.
ASSETS_DIR=${NIXPACKS_ASSETS_DIR:-/assets}
NGINX_CONFIG=${NIXPACKS_NGINX_CONFIG:-/nginx.conf}
if [ -f "$APP_DIR/nginx.conf" ]; then
    NGINX_CONFIG="$APP_DIR/nginx.conf"
else
    TEMPLATE="$ASSETS_DIR/nginx.template.conf"
    if [ -f "$APP_DIR/nginx.template.conf" ]; then TEMPLATE="$APP_DIR/nginx.template.conf"; fi
    node "$ASSETS_DIR/scripts/prestart.mjs" "$TEMPLATE" "$NGINX_CONFIG"
fi
php-fpm -y "$ASSETS_DIR/php-fpm.conf" &
exec nginx -c "$NGINX_CONFIG"
